const fs = require('node:fs');
const path = require('node:path');
const { getDefaultConfig } = require('expo/metro-config');
const { withNativeWind } = require('nativewind/metro');

const maplibreDist = path.join(path.dirname(require.resolve('maplibre-gl/package.json')), 'dist');
const maplibrePublic = path.join(__dirname, 'public', 'maplibre');
fs.mkdirSync(maplibrePublic, { recursive: true });
for (const file of ['maplibre-gl-worker.mjs', 'maplibre-gl-shared.mjs']) {
  fs.copyFileSync(path.join(maplibreDist, file), path.join(maplibrePublic, file));
}

const config = getDefaultConfig(__dirname);

// SVG files are imported as components (react-native-svg-transformer), not as image assets.
config.transformer.babelTransformerPath = require.resolve('react-native-svg-transformer/expo');
config.resolver.assetExts = config.resolver.assetExts.filter((ext) => ext !== 'svg');
config.resolver.sourceExts = [...config.resolver.sourceExts, 'svg'];

module.exports = withNativeWind(config, { input: './global.css' });
